// CEarthView::CEarthView( const SWindowInfo & ) @0x23f280 -- the live ctor. Zeroes the spin state,
// clears the parented scene, then for the fixed globe RPG item ( NDb::GetRPGItem(0x1E7) ) builds the
// camera from sCameras[2] (the canonical "camera from SCameraParams" idiom, cf. iCommonUI.cpp:858)
// and installs the model + camera transform.
////////////////////////////////////////////////////////////////////////////////////////////////////
CEarthView::CEarthView( const SWindowInfo &sInfo ):
	CModel( sInfo ), bButtonDown( false ), fAngleX( 0 ), fLastAngleX( 0 ), fAngleY( 0 ), fLastAngleY( 0 ), sLastPoint( 0, 0 )
{
	SetScene( 0, false );

	CPtr<NDb::CRPGItem> pRPGItem( NDb::GetRPGItem( 0x1E7 ) );
	if ( IsValid( pRPGItem ) )
	{
		const NDb::SCameraParams &sCamera = pRPGItem->sCameras[2];

		CVec3 vForwardDir;
		CQuat q = CQuat( sCamera.fYaw, V3_AXIS_Z ) * CQuat( sCamera.fPitch, V3_AXIS_X );
		q.GetYAxis( &vForwardDir );

		CVec3 vCP( sCamera.vAnchor - vForwardDir * sCamera.fDistance );
		SHMatrix sCameraTransform;
		MakeMatrix( &sCameraTransform, sCamera.fPitch, sCamera.fYaw, sCamera.fRoll, vCP );

		SRand sRnd;
		SetModel( pRPGItem->pModel->CreateModel( &sRnd ) );
		SetCameraTransform( sCameraTransform );

void CRPGItem::Import()
{
	NDatabase::ImportField( "Weight", &nWeight );
	NDatabase::ImportField( "SizeX",	&sSize.x );
	NDatabase::ImportField( "SizeY",	&sSize.y );
	NDatabase::ImportField( "TooltipID", &pToolTip );
	NDatabase::ImportField( "ModelID", &pModel );
	NDatabase::ImportField( "ModelActive1", &pModelActive );
	NDatabase::ImportField( "Model1", &pModelInactive );

class CRPGItem: public CDBRecord
{
	OBJECT_BASIC_METHODS(CRPGItem);
public:
	int nWeight; // in grams
	int nSubTypePriority;
	EItemSubType subType;
	CTPoint<int> sSize;
	CPtr<CString> pToolTip;
	CPtr<CString> pName;
	CPtr<CString> pDescription;
	CPtr<CTRndModel> pModel;
	CPtr<CTRndModel> pModelActive;
	CPtr<CTRndModel> pModelInactive;
	vector<SUniformItem> looks;
	SCameraParams sCameras[CAMERA_MAX_VALUE];

CModel *pModel = new CModel;
pModel->pGeometry = pGeometry;
pModel->pSkeleton = pSkeleton;
pModel->pRPGArmor = pRPGArmor;
// retail CreateModel @0x3f7670 stows the source CTRndModel template on the product
// (CModel::pSrcRndModel, save tag 12) so NRender can re-roll materials later.
pModel->pSrcRndModel = pTemplate;
for ( int i = 0; i < N_MODEL_MATERIALS; ++i )
	pModel->pMaterials[i] = IsValid( pMaterials[i] ) ? pMaterials[i]->GetRnd( pRand, flags ) : 0;
return pModel;

pO->bIsDeploySpot = bIsDeploySpot;
pO->nParentID = GetRecordID();
//pO->eType = eType;
//pO->pWeapon = pWeapon;
for ( int i = 0; i < N_DESTROY_STAGES; ++i )
	if ( pModels[i] )
		pO->pModels[i] = pModels[i]->CreateContainer( pRand, params );
if ( IsValid( pChild ) )
	pO->pChild = pChild->CreateObject( pRand, params );
ASSERT( IsValid( pTemplate ) );
